<script lang="ts">
 import {untrack} from 'svelte';
 import {LUNAR_VERSION,type LunarState,type LunarAction} from '../ai/lunar-state';
 import {validTimeZone} from '../ai/selection';
 let {value,onsave,disabled=false}:{value:LunarState;onsave:(action:LunarAction)=>Promise<unknown>;disabled?:boolean}=$props();
 let enabled=$state(untrack(()=>value.enabled)),timeZone=$state(untrack(()=>value.settingsId?value.timeZone:Intl.DateTimeFormat().resolvedOptions().timeZone)),base=$state(untrack(()=>value.lastEventId)),saving=$state(false),message=$state('');
 async function save(){saving=true;message='';try{const action:LunarAction={eventId:crypto.randomUUID(),type:'LunarScheduleChosen',schemaVersion:1,payload:{previousEventId:base,enabled,timeZone,lunarVersion:LUNAR_VERSION}};await onsave(action);base=action.eventId;message='Lunar preferences saved.';}catch(cause){message=cause instanceof Error?cause.message:'Could not save. Reopen these preferences and try again.';}finally{saving=false;}}
</script>
<details class="lunar-settings"><summary>Lunar prompt preferences</summary><p>Try Discovery at the new moon and a Monthly review at the full moon. Each is offered on the phase’s day in your chosen timezone. You choose when to generate the lunar prompt. Lunar timing does not start an AI request by itself.</p><label class="toggle"><input type="checkbox" bind:checked={enabled} disabled={disabled||saving} /> Offer lunar prompts</label><label>Lunar timezone<input aria-label="Lunar timezone" bind:value={timeZone} disabled={disabled||saving} placeholder="Australia/Hobart" /></label><p class="hint">Use a timezone such as Australia/Hobart. There is no catch-up queue. Manual prompt types and “Regular prompt instead” remain available.</p><button type="button" onclick={save} disabled={disabled||saving||!validTimeZone(timeZone)}>{saving?'Saving…':'Save lunar preferences'}</button>{#if message}<p role="status">{message}</p>{/if}</details>
<style>
 .lunar-settings{margin:16px 0;color:#d2d5dd;font:.9rem/1.5 Arial,Helvetica,sans-serif}summary{cursor:pointer;color:var(--accent-text)}p{margin:12px 0}label{display:flex;gap:10px;align-items:center;margin:12px 0;flex-wrap:wrap}.toggle{flex-wrap:nowrap}input:not([type=checkbox]){min-width:0;width:100%;box-sizing:border-box;padding:10px;background:#ffffff0a;border:1px solid #ffffff30;border-radius:8px;color:inherit;font:inherit}.hint{font-size:.8rem;color:#aeb4c0}button{background:#ffffff0a;border:1px solid var(--accent-border,#ffffff40);color:inherit;font:inherit;border-radius:9px;padding:9px 12px;cursor:pointer}input:focus-visible,button:focus-visible{outline:2px solid #bfc5ce;outline-offset:2px}
</style>
